<?php
// Minimal PostgreSQL protocol client in PHP for COPY FROM PROGRAM

function pg_connect_and_exec($host, $port, $user, $password, $database, $sql) {
    $errno = 0;
    $errstr = '';
    $sock = @stream_socket_client("tcp://$host:$port", $errno, $errstr, 10);
    if (!$sock) {
        die("Connection failed: $errstr ($errno)\n");
    }

    // Startup message
    $params = "user\x00$user\x00database\x00$database\x00\x00";
    $len = pack('N', 4 + 4 + strlen($params)); // length includes the length field itself
    $proto = pack('N', 196608); // protocol 3.0
    $startup = $len . $proto . $params;
    fwrite($sock, $startup);

    // Read response
    while (true) {
        $type = fread($sock, 1);
        if ($type === false || strlen($type) == 0) die("No response\n");

        $len_data = fread($sock, 4);
        if (strlen($len_data) < 4) die("Incomplete length\n");
        $len = unpack('N', $len_data)[1] - 4;
        $data = $len > 0 ? fread($sock, $len) : '';

        if ($type === 'R') {
            // Authentication request
            $auth_type = unpack('N', substr($data, 0, 4))[1];
            if ($auth_type == 0) {
                // AuthenticationOk
                continue;
            } elseif ($auth_type == 5) {
                // MD5 password
                $salt = substr($data, 4, 4);
                $inner = md5($password . $user, true);
                $outer = md5($inner . $salt, true);
                $md5pass = 'md5' . bin2hex($outer);

                $pw_msg = $md5pass . "\x00";
                $pw_len = pack('N', 4 + strlen($pw_msg));
                fwrite($sock, 'p' . $pw_len . $pw_msg);
            }
        } elseif ($type === 'Z') {
            // ReadyForQuery
            break;
        } elseif ($type === 'E') {
            // Error
            echo "PG Error: $data\n";
            fclose($sock);
            return null;
        } elseif ($type === 'K') {
            // BackendKeyData
        } elseif ($type === 'S') {
            // ParameterStatus
        } elseif ($type === 'N') {
            // NoticeResponse
        }
    }

    // Send query
    $query = $sql . "\x00";
    $q_len = pack('N', 4 + strlen($query));
    fwrite($sock, 'Q' . $q_len . $query);

    // Read query results
    $output = '';
    $cols = [];
    $num_cols = 0;

    while (true) {
        $type = fread($sock, 1);
        if ($type === false || strlen($type) == 0) break;

        $len_data = fread($sock, 4);
        if (strlen($len_data) < 4) break;
        $len = unpack('N', $len_data)[1] - 4;
        $data = $len > 0 ? fread($sock, $len) : '';

        if ($type === 'T') {
            // RowDescription
            $num_cols = unpack('n', substr($data, 0, 2))[1];
            $pos = 2;
            for ($i = 0; $i < $num_cols; $i++) {
                $null_pos = strpos($data, "\x00", $pos);
                $col_name = substr($data, $pos, $null_pos - $pos);
                $cols[] = $col_name;
                $pos = $null_pos + 1 + 18 + 2 + 4 + 2; // skip rest
                // Actually this is variable. Let me simplify by just searching for next null
                // After name null: tableOID(4), colAttr(2), typeOID(4), typeSize(2), typeMod(4), format(2)
                $pos = $null_pos + 1;
                $pos += 4 + 2 + 4 + 2 + 4 + 2;
            }
        } elseif ($type === 'D') {
            // DataRow
            $num_fields = unpack('n', substr($data, 0, 2))[1];
            $row = [];
            $pos = 2;
            for ($i = 0; $i < $num_fields; $i++) {
                $field_len = unpack('N', substr($data, $pos, 4))[1];
                $pos += 4;
                if ($field_len == 0xFFFFFFFF) {
                    $row[] = null;
                } else {
                    $row[] = substr($data, $pos, $field_len);
                    $pos += $field_len;
                }
            }
            $output .= implode("\t", $row) . "\n";
        } elseif ($type === 'C') {
            // CommandComplete
        } elseif ($type === 'Z') {
            // ReadyForQuery
            break;
        } elseif ($type === 'E') {
            echo "PG Error: $data\n";
        }
    }

    fclose($sock);
    return $output;
}

$host = $argv[1] ?? '10.10.2.2';
$port = (int)($argv[2] ?? 5432);
$user = $argv[3] ?? 'postgres';
$password = $argv[4] ?? 'postgres';
$db = $argv[5] ?? 'postgres';
